WITH store_sales_agg AS ( SELECT i.i_category AS category, SUM(ss.ss_quantity) AS store_sales_qty, SUM(ss.ss_ext_sales_price) AS store_sales_amount FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk WHERE ss.ss_sold_date_sk BETWEEN 2450000 AND 2459999 GROUP BY i.i_category ), web_sales_agg AS ( SELECT i.i_category AS category, SUM(ws.ws_quantity) AS web_sales_qty, SUM(ws.ws_ext_sales_price) AS web_sales_amount FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk WHERE ws.ws_sold_date_sk BETWEEN 2450000 AND 2459999 GROUP BY i.i_category ), catalog_returns_agg AS ( SELECT i.i_category AS category, SUM(cr.cr_return_quantity) AS catalog_return_qty, SUM(cr.cr_return_amount) AS catalog_return_amount, SUM(cr.cr_net_loss) AS catalog_net_loss FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk WHERE cr.cr_returned_date_sk BETWEEN 2450000 AND 2459999 AND sm.sm_type = 'AIR' GROUP BY i.i_category ), store_returns_agg AS ( SELECT i.i_category AS category, SUM(sr.sr_return_quantity) AS store_return_qty, SUM(sr.sr_return_amt) AS store_return_amount, SUM(sr.sr_net_loss) AS store_net_loss FROM store_returns sr JOIN store_sales ss ON sr.sr_ticket_number = ss.ss_ticket_number AND sr.sr_item_sk = ss.ss_item_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk WHERE sr.sr_returned_date_sk BETWEEN 2450000 AND 2459999 GROUP BY i.i_category ) SELECT COALESCE(ssa.category, wsa.category, cra.category, sra.category) AS category, COALESCE(ssa.store_sales_qty, 0) + COALESCE(wsa.web_sales_qty, 0) AS total_sales_qty, COALESCE(ssa.store_sales_amount, 0) + COALESCE(wsa.web_sales_amount, 0) AS total_sales_amount, COALESCE(cra.catalog_return_qty, 0) + COALESCE(sra.store_return_qty, 0) AS total_return_qty, COALESCE(cra.catalog_return_amount, 0) + COALESCE(sra.store_return_amount, 0) AS total_return_amount, COALESCE(cra.catalog_net_loss, 0) + COALESCE(sra.store_net_loss, 0) AS total_return_net_loss, (COALESCE(cra.catalog_return_qty, 0) + COALESCE(sra.store_return_qty, 0)) / NULLIF(COALESCE(ssa.store_sales_qty, 0) + COALESCE(wsa.web_sales_qty, 0), 0) AS return_qty_rate, (COALESCE(cra.catalog_return_amount, 0) + COALESCE(sra.store_return_amount, 0)) / NULLIF(COALESCE(ssa.store_sales_amount, 0) + COALESCE(wsa.web_sales_amount, 0), 0) AS return_amount_rate, (COALESCE(cra.catalog_net_loss, 0) + COALESCE(sra.store_net_loss, 0)) / NULLIF((COALESCE(cra.catalog_return_qty, 0) + COALESCE(sra.store_return_qty, 0)), 0) AS avg_net_loss_per_return FROM store_sales_agg ssa FULL OUTER JOIN web_sales_agg wsa ON ssa.category = wsa.category FULL OUTER JOIN catalog_returns_agg cra ON COALESCE(ssa.category, wsa.category) = cra.category FULL OUTER JOIN store_returns_agg sra ON COALESCE(ssa.category, wsa.category, cra.category) = sra.category WHERE (COALESCE(ssa.store_sales_qty, 0) + COALESCE(wsa.web_sales_qty, 0)) > 0 ORDER BY total_return_amount DESC LIMIT 100
